// =============================================================================
//  ADS131M02 backend for the RP2040/RP2350.
//
//   * CLKIN: 5.12 MHz generated by a PWM slice from clk_sys (153.6 MHz / 30 on
//     RP2350, 128 MHz / 25 on RP2040) -> ODR = CLKIN / 2 / OSR is phase-locked
//     to the MCU clock (exactly 10.000 kS/s at OSR 256; no drift between the
//     sample clock and the timestamps).
//   * Configuration: hardware SPI0 (mode 1), register write + read-back check.
//   * Streaming: a PIO state machine waits for DRDY, clocks one 96-bit frame
//     (STATUS | CH0 | CH1 | CRC) and autopushes 3 words; DMA moves them into a
//     16-block ring with a second "control" DMA channel re-arming the data
//     channel from an address table -> zero CPU work per sample, one IRQ per
//     block (5 ms) that only increments a counter and timestamps the block.
//   * readBlock() decodes frames, checks CRC / status / saturation, and
//     detects overruns (consumer lagging by >= ring size) and missing samples
//     (block completion timestamps inconsistent with the ODR).
// =============================================================================
#pragma once
#include <cstdint>

#include "adc/adc_interface.h"
#include "hardware/pio.h"

namespace pq {

class Ads131m02Backend : public AdcBackend {
public:
    const char* name() const override { return "ads131m02"; }
    AdcStatus   init(const AdcHwConfig& cfg) override;
    AdcStatus   start() override;
    void        stop() override;
    bool        readBlock(RawBlock& out) override;
    AdcStatus   poll() override;
    float       actualSampleRate() const override { return odr_; }
    int32_t     fullScaleCounts() const override { return 0x7FFFFF; }
    const AdcDiagnostics& diagnostics() const override { return diag_; }

    uint16_t deviceId() const { return id_; }
    static void dmaIrqHandler();

private:
    static constexpr int kWordsPerSample = 3;   // 96 bits
    static constexpr int kBlockWords = kWordsPerSample * static_cast<int>(kBlockSize);

    AdcStatus spiFrame(uint16_t cmd, const uint16_t* data, int ndata, uint16_t* first_word_of_reply);
    AdcStatus readReg(uint8_t reg, uint16_t& val);
    AdcStatus writeRegChecked(uint8_t reg, uint16_t val);
    void      pinsToSpi();
    void      pinsToPio();
    bool      startClkin();
    void      buildPioProgram();

    AdcHwConfig    cfg_{};
    AdcDiagnostics diag_{};
    float    odr_ = 10000.0f;
    uint32_t clkin_hz_ = 0;
    uint16_t id_ = 0;
    bool     inited_ = false;
    bool     running_ = false;

    PIO      pio_ = nullptr;
    int      sm_ = -1;
    int      prog_offset_ = -1;
    uint16_t prog_[8];
    int      dma_data_ = -1;
    int      dma_ctrl_ = -1;
    uint32_t consumed_ = 0;
    uint64_t t_start_us_ = 0;
    bool     gap_pending_ = false;
};

}  // namespace pq
